(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin(x*0.035-t*0.5)*8+Math.cos(y*0.028+t*0.45)*6;
  const w2y = Math.cos(y*0.032+t*0.55)*8+Math.sin(x*0.025-t*0.4)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0.5],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.6],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 0.4],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.7],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 0.3],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.55],
    [80+Math.sin(t*0.45+1.5)*110, 40+Math.cos(t*0.65+2.5)*60, 0.11, 2.1, 0.45],
    [400+Math.cos(t*0.38+3)*100, 190+Math.sin(t*0.52+4)*70, 0.065, 2.4, 0.65],
    [200+Math.sin(t*0.72)*60, 220+Math.cos(t*0.48)*40, 0.14, 1.3, 0.5],
    [300+Math.cos(t*0.55+2)*70, 30+Math.sin(t*0.85+1)*50, 0.075, 2.8, 0.35]
  ];
  let aS=0, iS=0, hS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const w1 = Math.sin(d*f-t*sp);
    const w2 = Math.sin(d*f*1.618-t*sp*0.618+1.0);
    aS += (w1+w2*0.3)*w;
    iS += (Math.sin(d*f*0.7+t*sp*0.6+1.5)+Math.sin(d*f*0.5-t*sp*0.4+2.8)*0.4)*w;
    hS += Math.sin(d*f*0.3+t*sp*0.3+3.0)*w;
  }
  const nw = aS/6, ni = iS/6, nh = hS/6;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2
    + Math.sin(sx*0.07*Math.cos(t*0.2)+sy*0.05*Math.sin(t*0.15)+t*1.8)*0.15;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    + Math.sin(dist*0.03-ang*5+t*0.8)*0.2 + Math.sin(dist*0.065+ang*2-t*2.2)*0.15;
  const voronoi = (() => {
    let md = 999, md2 = 999;
    for (let i = 0; i < 12; i++) {
      const a = i*Math.PI*2/12+t*0.15;
      const r = 60+Math.sin(t*0.3+i*1.3)*30;
      const px = cx+Math.cos(a)*r, py = cy+Math.sin(a)*r;
      const d = Math.sqrt((sx-px)**2+(sy-py)**2);
      if (d < md) { md2 = md; md = d; } else if (d < md2) { md2 = d; }
    }
    return (md2-md)*0.08;
  })();
  const laplacian = (() => {
    const c = nw-ni*0.7+bg*0.3+spiral;
    const step = 2;
    const dx = ((Math.sin((sx+step-cx)**2*0.001+(sy-cy)**2*0.001)*2)-c)*0.5;
    const dy = ((Math.sin((sx-cx)**2*0.001+(sy+step-cy)**2*0.001)*2)-c)*0.5;
    return (dx+dy)*0.25;
  })();
  const reaction = Math.tanh((nw-ni*0.7+bg*0.3+spiral+voronoi+laplacian)*2.2);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro = Math.sin(sx*0.4+t*3)*Math.sin(sy*0.4-t*2.5)*0.08;
  const pulse = 1+Math.sin(t*0.8)*0.05;
  const blend = (reaction*0.6+cell*0.2+micro)*pulse+nh*0.12;
  const v = blend*0.5+0.5;
  const pal = [
    [5,10,45],[10,40,85],[12,75,120],[18,125,130],[35,165,145],
    [120,185,100],[210,190,60],[230,145,55],[215,90,65],[180,50,75],
    [130,30,65],[70,15,50],[30,8,40],[5,10,45]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const smf = f*f*(3-2*f);
  const lum = 0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge = Math.abs(reaction)>0.7?1.2:Math.abs(reaction)>0.4?1.05:0.95;
  const glow = Math.max(0, 1-Math.abs(reaction))*0.15;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*smf)*lum*edge+glow*80))|0,
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*smf)*lum*edge+glow*60))|0,
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*smf)*lum*edge+glow*120))|0
  ];
}
